@Ordinal.type_le_iff.{u_1} : ∀ {α β : Type u_1} {r : α → α → Prop} {s : β → β → Prop} [inst : IsWellOrder.{u_1} α r]
  [inst_1 : IsWellOrder.{u_1} β s],
  Iff
    (@LE.le.{u_1 + 1} Ordinal.{u_1}
      (@Preorder.toLE.{u_1 + 1} Ordinal.{u_1}
        (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1}))
      (@Ordinal.type.{u_1} α r inst) (@Ordinal.type.{u_1} β s inst_1))
    (Nonempty.{u_1 + 1} (@InitialSeg.{u_1, u_1} α β r s))

@Ordinal.enum.{u_1} : {α : Type u_1} →
  (r : α → α → Prop) →
    [inst : IsWellOrder.{u_1} α r] →
      @RelIso.{u_1 + 1, u_1}
        (@Set.Elem.{u_1 + 1} Ordinal.{u_1}
          (@Set.Iio.{u_1 + 1} Ordinal.{u_1}
            (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1})
            (@Ordinal.type.{u_1} α r inst)))
        α
        (fun x1 x2 =>
          @LT.lt.{u_1 + 1}
            (@Set.Elem.{u_1 + 1} Ordinal.{u_1}
              (@Set.Iio.{u_1 + 1} Ordinal.{u_1}
                (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1})
                (@Ordinal.type.{u_1} α r inst)))
            (@Subtype.instLT.{u_1 + 1} Ordinal.{u_1}
              (@Preorder.toLT.{u_1 + 1} Ordinal.{u_1}
                (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1}))
              fun x =>
              @Membership.mem.{u_1 + 1, u_1 + 1} Ordinal.{u_1} (Set.{u_1 + 1} Ordinal.{u_1})
                (@Set.instMembership.{u_1 + 1} Ordinal.{u_1})
                (@Set.Iio.{u_1 + 1} Ordinal.{u_1}
                  (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1})
                  (@Ordinal.type.{u_1} α r inst))
                x)
            x1 x2)
        r

@Ordinal.typein.{u_1} : {α : Type u_1} →
  (r : α → α → Prop) →
