    (@Ordinal.type.{u_1 + 1}
      (@Set.Elem.{u_1 + 1} Ordinal.{u_1}
        (@Set.Iio.{u_1 + 1} Ordinal.{u_1} (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1})
          o))
      (fun x1 x2 =>
        @LT.lt.{u_1 + 1}
          (@Set.Elem.{u_1 + 1} Ordinal.{u_1}
            (@Set.Iio.{u_1 + 1} Ordinal.{u_1}
              (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1}) o))
          (@Subtype.instLT.{u_1 + 1} Ordinal.{u_1}
            (@Preorder.toLT.{u_1 + 1} Ordinal.{u_1}
              (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1}))
