    (@Preorder.toLE.{u_1} o.ToType
      (@instPreorderShrink.{u_1, u_1 + 1}
        (@Set.Elem.{u_1 + 1} Ordinal.{u_1}
          (@Set.Iio.{u_1 + 1} Ordinal.{u_1}
            (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1}) o))
        ⋯
        (@Subtype.preorder.{u_1 + 1} Ordinal.{u_1}
          (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1}) fun x =>
          @Membership.mem.{u_1 + 1, u_1 + 1} Ordinal.{u_1} (Set.{u_1 + 1} Ordinal.{u_1})
            (@Set.instMembership.{u_1 + 1} Ordinal.{u_1})
            (@Set.Iio.{u_1 + 1} Ordinal.{u_1}
              (@PartialOrder.toPreorder.{u_1 + 1} Ordinal.{u_1} Ordinal.partialOrder.{u_1}) o)
            x)))

